@Override public boolean onNavigationItemSelected(@NonNull MenuItem item){
  final int action=item.getItemId();
  try {
    switch (action) {
      case R.id.action_delete: 
        onActionDiscard();
        break;
      case R.id.action_send:
        onActionCheck(false);
        break;
      default:
        onAction(action);
    }
  } catch (SecurityException e) {
    Log.e("Navigation", "Security exception during file operation", e);
  } catch (UnsupportedOperationException e) {
    Log.e("Navigation", "Unsupported operation on collection", e);
  } catch (RejectedExecutionException e) {
    Log.e("Navigation", "Task execution rejected", e);
  }
  return true;
}
